          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Sağ elindekini at da onların yaptıklarını yutsun, yaptıkları sadece sihirbaz düzenidir. Sihirbaz nereden gelirse gelsin başarı kazanamaz"
